  // The model is a non-notifying List. Keep its membership/order changes out of
  // WPF's generator while an asynchronous save/restart is still in progress.
  // Rows themselves remain shared so in-place TCP/UDP updates keep their layout.
  RouteList[] RouteTableSnapshot(){return session.State.Lists.ToArray();}
  void RestoreRouteTable(DataGrid table){var selected=table.SelectedItems.Cast<RouteList>().Select(r=>r.Id).ToArray();var scroll=FindScrollViewer(table);double vertical=scroll==null?0:scroll.VerticalOffset,horizontal=scroll==null?0:scroll.HorizontalOffset;table.ItemsSource=RouteTableSnapshot();foreach(var row in session.State.Lists.Where(r=>selected.Contains(r.Id)))table.SelectedItems.Add(row);Dispatcher.BeginInvoke(new Action(()=>{if(!table.IsLoaded)return;var currentScroll=FindScrollViewer(table);if(currentScroll!=null){currentScroll.ScrollToVerticalOffset(vertical);currentScroll.ScrollToHorizontalOffset(horizontal);}}),System.Windows.Threading.DispatcherPriority.Loaded);}
  async Task RouteTransportChange(DataGrid table,CheckBox check,string id,bool tcp){
   bool desired=check.IsChecked==true;
   try{await Run(async()=>{
    // Validate a copy first: rejecting an unsafe rule must not replace the
    // entire state/page and destroy column sizing, selection or focus.
    var currentRoute=session.State.Lists.Single(r=>r.Id==id);var json=new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue};var proposed=json.Deserialize<RouteList>(json.Serialize(currentRoute));if(tcp)proposed.GameFilterTcp=desired;else proposed.GameFilterUdp=desired;if(proposed.Enabled)ZapretRoutes.Validate(proposed,session.State.ZapretProfiles);
    await RouteChange(()=>{var route=session.State.Lists.Single(r=>r.Id==id);if(tcp)route.GameFilterTcp=desired;else route.GameFilterUdp=desired;},false);
    status.Text=(tcp?"TCP":"UDP")+" · изменение сохранено.";
   },()=>RestoreRouteTable(table));}
   finally{var actual=session.State.Lists.FirstOrDefault(r=>r.Id==id);if(actual!=null)check.IsChecked=tcp?actual.GameTcpEnabled:actual.GameUdpEnabled;}
  }
